<?php
require_once __DIR__.'/_layout.php';$total=(int)$pdo->query('SELECT COUNT(*) FROM bookings')->fetchColumn();$customers=(int)$pdo->query("SELECT COUNT(*) FROM users WHERE role='customer'")->fetchColumn();$rooms=(int)$pdo->query('SELECT COUNT(*) FROM rooms')->fetchColumn();$available=(int)$pdo->query("SELECT COUNT(*) FROM rooms WHERE status='available'")->fetchColumn();$pending=(int)$pdo->query("SELECT COUNT(*) FROM bookings WHERE status='pending'")->fetchColumn();$confirmed=(int)$pdo->query("SELECT COUNT(*) FROM bookings WHERE status='confirmed'")->fetchColumn();$recent=$pdo->query('SELECT b.*,r.room_name FROM bookings b JOIN rooms r ON b.room_id=r.room_id ORDER BY b.created_at DESC LIMIT 8')->fetchAll();$monthly=$pdo->query("SELECT DATE_FORMAT(created_at,'%b') m, COUNT(*) c, MONTH(created_at) n FROM bookings WHERE created_at>=DATE_SUB(CURDATE(),INTERVAL 6 MONTH) GROUP BY YEAR(created_at),MONTH(created_at),m,n ORDER BY YEAR(created_at),n")->fetchAll();$statuses=$pdo->query('SELECT status,COUNT(*) c FROM bookings GROUP BY status')->fetchAll();$rev=$pdo->query("SELECT DATE_FORMAT(created_at,'%b') m, SUM(total_amount) total,MONTH(created_at) n FROM bookings WHERE status='confirmed' AND created_at>=DATE_SUB(CURDATE(),INTERVAL 6 MONTH) GROUP BY YEAR(created_at),MONTH(created_at),m,n ORDER BY YEAR(created_at),n")->fetchAll();admin_start('Welcome back, '.current_user()['name']);?>
<p style="color:var(--muted)">A thoughtful overview of the house.</p><div class="stat-grid"><div class="stat-card"><small>Total bookings</small><strong><?= $total ?></strong></div><div class="stat-card"><small>Registered guests</small><strong><?= $customers ?></strong></div><div class="stat-card"><small>Rooms · <?= $available ?> available</small><strong><?= $rooms ?></strong></div><div class="stat-card"><small>Pending reservations</small><strong><?= $pending ?></strong></div></div><div class="chart-grid"><div class="chart-panel"><h3>Bookings by month</h3><canvas id="monthly"></canvas></div><div class="chart-panel"><h3>Reservation status</h3><canvas id="statuses"></canvas></div><div class="chart-panel"><h3>Confirmed revenue</h3><canvas id="revenue"></canvas></div><div class="chart-panel"><h3>At a glance</h3><p><?= $confirmed ?> confirmed reservations</p><p><?= max(0,$rooms-$available) ?> rooms not currently available</p><p><?= $customers ?> guests have an account</p></div></div><h2 style="font:25px var(--serif);color:var(--navy)">Recent activity</h2><table class="data-table"><thead><tr><th>Reference</th><th>Guest</th><th>Room</th><th>Arrival</th><th>Amount</th><th>Status</th></tr></thead><tbody><?php foreach($recent as $b): ?><tr><td><?= e($b['booking_reference']) ?></td><td><?= e($b['guest_name']) ?></td><td><?= e($b['room_name']) ?></td><td><?= e($b['check_in']) ?></td><td>₹<?= number_format((float)$b['total_amount']) ?></td><td><?= e($b['status']) ?></td></tr><?php endforeach; ?></tbody></table><script src="https://cdn.jsdelivr.net/npm/chart.js"></script><script>new Chart(document.getElementById('monthly'),{type:'line',data:{labels:<?= json_encode(array_column($monthly,'m')) ?>,datasets:[{data:<?= json_encode(array_map('intval',array_column($monthly,'c'))) ?>,borderColor:'#b59a69',backgroundColor:'#b59a6924',fill:true,tension:.35}]},options:{plugins:{legend:{display:false}}}});new Chart(document.getElementById('statuses'),{type:'doughnut',data:{labels:<?= json_encode(array_column($statuses,'status')) ?>,datasets:[{data:<?= json_encode(array_map('intval',array_column($statuses,'c'))) ?>,backgroundColor:['#b59a69','#182a35','#d8cbb7','#a86f5d']}]}});new Chart(document.getElementById('revenue'),{type:'bar',data:{labels:<?= json_encode(array_column($rev,'m')) ?>,datasets:[{data:<?= json_encode(array_map('floatval',array_column($rev,'total'))) ?>,backgroundColor:'#b59a69'}]},options:{plugins:{legend:{display:false}}}});</script><?php admin_end(); ?>
